/* Hermetic stand-in for https://www.paypal.com/sdk/js (see e2e/04-alternative-payments/popups.spec.ts).
   Mirrors what the real PayPal JS does with the config the SDK passes to paypal.Buttons():
   a click opens the checkout popup synchronously, createOrder() supplies the order id the popup
   then navigates to, and closing the popup calls onCancel(). */
(function () {
  function Buttons(cfg) {
    return {
      isEligible: function () { return true; },
      render: function (selector) {
        var host = document.querySelector(selector);
        var btn = document.createElement("button");
        btn.type = "button";
        btn.setAttribute("data-hermetic", "paypal-button");
        btn.setAttribute("data-funding-source", cfg.fundingSource || "");
        btn.setAttribute("aria-label", "PayPal");
        btn.textContent = "PayPal";
        btn.style.cssText = "width:100%;height:" + ((cfg.style && cfg.style.height) || 48) + "px";
        btn.addEventListener("click", function () {
          if (cfg.onClick) cfg.onClick();
          var popup = window.open("", "hermetic_paypal_checkout", "width=450,height=650");
          Promise.resolve(cfg.createOrder()).then(
            function (orderId) {
              if (popup && !popup.closed) {
                popup.location.href = "https://www.sandbox.paypal.com/checkoutnow?token=" + encodeURIComponent(orderId);
              }
            },
            function (err) {
              if (popup) popup.close();
              if (cfg.onError) cfg.onError(err);
            }
          );
          var timer = setInterval(function () {
            if (!popup || popup.closed) {
              clearInterval(timer);
              if (cfg.onCancel) cfg.onCancel({ orderID: null });
            }
          }, 100);
        });
        host.appendChild(btn);
        return Promise.resolve();
      },
    };
  }
  window.paypal = { Buttons: Buttons, FUNDING: { PAYPAL: "paypal" }, version: "hermetic" };
})();

/* Hermetic stand-in for https://x.klarnacdn.net/kp/lib/v1/api.js (see e2e/04-alternative-payments/popups.spec.ts).
   Mirrors the Klarna Payments express-button API the SDK uses (Klarna.Payments.Buttons.init/load):
   load() renders the button and reports it loaded; a click calls the SDK's on_click with an
   authorize() that opens Klarna's purchase popup and, when the shopper closes it without
   finishing, calls back with approved:false (what Klarna reports for an abandoned purchase). */
(function () {
  var clientToken = "";
  var Buttons = {
    init: function (opts) {
      clientToken = (opts && opts.client_token) || "";
      return Buttons;
    },
    load: function (opts, onLoaded) {
      var host = document.querySelector(opts.container);
      var btn = document.createElement("button");
      btn.type = "button";
      btn.setAttribute("data-hermetic", "klarna-button");
      btn.setAttribute("aria-label", "Klarna");
      btn.textContent = "Pay with Klarna";
      btn.style.cssText = "width:100%;height:48px";
      btn.addEventListener("click", function () {
        opts.on_click(function authorize(attrs, data, callback) {
          var popup = window.open(
            "https://js.playground.klarna.com/eu/kp/checkout/hermetic?client_token=" + encodeURIComponent(clientToken),
            "hermetic_klarna_checkout",
            "width=450,height=650"
          );
          var timer = setInterval(function () {
            if (!popup || popup.closed) {
              clearInterval(timer);
              callback({ approved: false, show_form: true, authorization_token: "", finalize_required: false });
            }
          }, 100);
        });
      });
      host.appendChild(btn);
      if (onLoaded) onLoaded({ show_form: true });
    },
  };
  window.Klarna = { Payments: { Buttons: Buttons } };
})();

/* Hermetic stand-in for https://cdn.plaid.com/link/v2/stable/link-initialize.js (see e2e/04-alternative-payments/popups.spec.ts).
   Like the real Link initializer, Plaid.create() injects the Link iframe (link.html?token=...)
   into the page, open() shows it, and when the shopper closes Link the iframe posts a message
   that makes the initializer hide it and call onExit(). */
(function () {
  var count = 0;
  function create(cfg) {
    count += 1;
    var iframe = document.createElement("iframe");
    iframe.id = "plaid-link-iframe-" + count;
    iframe.title = "Plaid Link";
    iframe.src = "https://cdn.plaid.com/link/v2/stable/link.html?isLinkInitialize=true&token=" + encodeURIComponent(cfg.token);
    iframe.style.cssText = "display:none;position:fixed;top:0;left:0;width:100%;height:100%;border:0;z-index:2147483647";
    document.body.appendChild(iframe);
    window.addEventListener("message", function (ev) {
      if (ev.source !== iframe.contentWindow || !ev.data || ev.data.hermetic_plaid_link !== "exit") return;
      iframe.style.display = "none";
      if (cfg.onExit) cfg.onExit(null, { status: null, link_session_id: "hermetic-link-session" });
    });
    if (cfg.onLoad) setTimeout(cfg.onLoad, 0);
    return {
      open: function () { iframe.style.display = "block"; },
      exit: function () { iframe.style.display = "none"; if (cfg.onExit) cfg.onExit(null, {}); },
      destroy: function () { iframe.remove(); },
      submit: function () {},
    };
  }
  window.Plaid = { create: create, version: "hermetic" };
})();
